SELECT id, product_id, last_restock, LAG(quantity, 1) OVER (ORDER BY quantity, id) AS prev_quantity, AVG(quantity) OVER (ORDER BY last_restock, id ROWS BETWEEN 5 PRECEDING AND 1 PRECEDING) AS quantity_avg_5_prior, SUM(quantity) OVER (PARTITION BY store_id, product_id) AS store_id_sum_quantity, LEAD(quantity, 1) OVER (PARTITION BY store_id, product_id ORDER BY quantity, id) AS next_quantity, ROW_NUMBER() OVER (PARTITION BY product_id ORDER BY last_restock, id) AS seq_no FROM inventory WHERE product_id IN (4, 6, 8);
